INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H', 'agriculture', 9, 'Describe the methods of conserving forage to cope with drought', ARRAY['AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.a']::text[], 'Describes the methods of conserving forage to cope with drought (haymaking by baling or stacking, standing forage left uncut, keeping crop residues such as maize stover) and says why conserved feed keeps animals alive in a drought, and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the method","match method and picture","story with a reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAYMAKING', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H', 'agriculture', 9, 'Say how hay is made, baled or stacked and stored', ARRAY['AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.b']::text[], 'Says how hay is made: cut grass at flowering, dry it in the sun and turn it until it is dry but still green, bale it in a box baler or stack it on a raised base with a sloping top, cover it from rain, store it dry and off the ground, and feed it in the dry season; in the app the child picks the right step, order, material, reason or method in new situations. The practical (conserving forage by stacking or box-baling) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the reason","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_WHY', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD', 'agriculture', 9, 'Explain why leftover food should be conserved and kept safe', ARRAY['AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.a']::text[], 'Explains why leftover food is conserved at home (saves money and food, less waste) and how it is kept safe (cooled quickly, covered, kept cool and used within a day), and says unsafe leftovers cause food poisoning, and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the reason","story","spot the error"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_PREP', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD', 'agriculture', 9, 'Say how leftover food is reheated safely or made into a new dish', ARRAY['AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.b']::text[], 'Says how leftover food is prepared: check it smells and looks fine, reheat it once until steaming hot all through, or turn it into a new dish (fried rice, fried ugali, mukimo, soup), serve at once, and throw away food left out too long or reheated before; in the app the child picks the right step, order, material, reason or method in new situations. The practical (preparing leftover food to avoid wastage) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the recipe","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_PARTS', 'AGRI.G9.CONSER.INTEGRATED_FARMING', 'agriculture', 9, 'Describe the components of integrated farming and how each conserves resources', ARRAY['AGRI.G9.CONSER.INTEGRATED_FARMING.a']::text[], 'Describes the components of integrated farming (fish rearing, rabbit keeping, poultry, vegetables, fruit trees, compost) on one plot and how each one''s waste becomes another''s input, conserving land, water, feed and money, and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["match the component","story","choose the reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_MODEL', 'AGRI.G9.CONSER.INTEGRATED_FARMING', 'agriculture', 9, 'Say how an integrated farming model is designed to show the links between its parts', ARRAY['AGRI.G9.CONSER.INTEGRATED_FARMING.b']::text[], 'Says how an integrated farming model is designed: sketch the plot, place each component where it can feed the next (rabbit hutch over the fish pond, poultry near the vegetables, compost near the garden), show the links with arrows (droppings to pond and garden, pond water to crops, crop waste to animals), choose materials and build it; in the app the child picks the right step, order, material, reason or method in new situations. The practical (making a model of integrated farming) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the link","spot the error"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_PRACTICES', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING', 'agriculture', 9, 'Explain organic gardening practices in crop production', ARRAY['AGRI.G9.FOOD_P.ORGANIC_GARDENING.a']::text[], 'Explains organic gardening practices (organic manure and compost, organic pesticides, mechanical weed control, foliar feeds from animal waste and plants such as Mexican sunflower, crop rotation, mulching) and how they give healthy food without synthetic chemicals, and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the practice","story","spot the error"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_INPUTS', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING', 'agriculture', 9, 'Say how organic inputs are prepared and used on a crop', ARRAY['AGRI.G9.FOOD_P.ORGANIC_GARDENING.b']::text[], 'Says how organic inputs are prepared and used: compost made and dug in, a foliar feed made by soaking chopped Mexican sunflower or manure in water for two weeks and diluting it, an organic spray of chilli, garlic, ash or neem, applied early in the morning or evening, and weeds removed by hand or jembe; in the app the child picks the right step, order, material, reason or method in new situations. The practical (growing a crop using organic gardening practices) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the input","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_PREP', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE', 'agriculture', 9, 'Say how a storage structure is prepared before crop produce is stored', ARRAY['AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.a', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.b']::text[], 'Says how a store, granary, container or bag is prepared: empty last season''s produce, clean and dust, seal cracks, repair leaks, put in pallets and rat guards, and let it dry and air before the new produce goes in; in the app the child picks the right step, order, material, reason or method in new situations. The practical (preparing an existing storage structure) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the reason","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_MANAGE', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE', 'agriculture', 9, 'Say how stored crop produce is managed to reduce spoilage', ARRAY['AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.c']::text[], 'Says how stored produce is managed: check moisture of cereals and pulses (bite or salt test), keep air moving, control rodents, turn the produce, look for pests, mould and heating, and remove and dispose of spoilt produce quickly; in the app the child picks the right step, order, material, reason or method in new situations. The practical (managing stored crop produce) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the action","order the checks","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_MIXTURES', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT', 'agriculture', 9, 'Identify the types of flour mixtures used in food production', ARRAY['AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.a']::text[], 'Identifies the types of flour mixtures: batters (runny: more liquid than flour, poured, for pancakes and crepes) and doughs (stiff: more flour than liquid, kneaded and shaped, for chapati, mandazi and bread), and matches products to each, and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["match mixture and product","choose the type","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.MIXTURE_PREP', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT', 'agriculture', 9, 'Say how batters and doughs are prepared', ARRAY['AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.b']::text[], 'Says how flour mixtures are prepared: measure ingredients, sift flour, for a batter beat in eggs and liquid gradually to a smooth pouring mixture and rest it, for a dough add liquid little by little, knead until smooth and elastic, rest it covered; in the app the child picks the right step, order, material, reason or method in new situations. The practical (preparing batters and doughs) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the measure","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_PRODUCTS', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT', 'agriculture', 9, 'Say how products are made from flour mixtures and tell when they are cooked', ARRAY['AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.c']::text[], 'Says how products are made: pancakes (pour batter thinly into a hot greased pan, turn when bubbles burst), chapati (roll, oil and fold, roll thin, cook both sides on a hot pan), mandazi (roll, cut, deep fry in hot oil by an adult until golden), and how to tell each is cooked; in the app the child picks the right step, order, material, reason or method in new situations. The practical (making pancakes, chapati or mandazi) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the method","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_WHY', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_', 'agriculture', 9, 'Explain why waste disposal facilities must be kept clean', ARRAY['AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.a']::text[], 'Explains why waste bins, sinks and open drains are cleaned (they breed flies, mosquitoes, rats and germs that spread diseases such as cholera and typhoid, smell, block and flood), naming the risk from each facility, and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the reason","story","match facility and risk"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_CLEAN', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_', 'agriculture', 9, 'Say how bins, sinks and open drains are cleaned and kept clean', ARRAY['AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.b']::text[], 'Says how waste facilities are cleaned at home: protective clothing on, empty the bin and scrub it with soap and water, dry it in the sun with the lid open, clear food from the sink strainer and scrub the sink and pipe, remove silt and rubbish from the drain so water flows, dispose of waste safely, wash hands; in the app the child picks the right step, order, material, reason or method in new situations. The practical (cleaning waste disposal facilities at the household level) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the tool","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_METHODS', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN', 'agriculture', 9, 'Describe the methods of disinfecting clothing and household articles', ARRAY['AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.a']::text[], 'Describes the methods of disinfecting clothing and household articles (sunlight, salt solution, boiling, disinfectants diluted as the label says, ironing) and which suits which article (boiling for white cotton towels and handkerchiefs, sunlight for most, ironing for cotton), and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["match method and article","choose the reason","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_PRACTICE', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN', 'agriculture', 9, 'Say how clothing and household articles are disinfected safely', ARRAY['AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.b']::text[], 'Says how to disinfect an article: wash it clean first, choose the method for the fabric, boil white cottons for 10 to 15 minutes, soak in salt water, dry in full sun, iron with a hot iron, use a chemical disinfectant only diluted by an adult and rinse it out, and store the clean article dry; in the app the child picks the right step, order, material, reason or method in new situations. The practical (disinfecting clothing and household articles) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the method","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_MEANING', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS', 'agriculture', 9, 'Describe grafting as a method of plant propagation', ARRAY['AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.a']::text[], 'Describes grafting: joining a scion (a shoot or bud from a good plant) to a rootstock (a strong rooted plant) so they grow as one; names the scion, rootstock and union, the common grafts (cleft, whip, side) and crops grafted (mango, avocado, citrus), and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the part","choose the reason","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_STEPS', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS', 'agriculture', 9, 'Say the steps of carrying out a graft', ARRAY['AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.b']::text[], 'Says the steps of a graft: choose a healthy rootstock and a scion from a good mother plant of the same kind, make clean matching cuts with a sharp clean knife (by an adult or with an adult beside), fit the cambium layers together, wrap firmly with grafting tape, cover the scion top, and label; in the app the child picks the right step, order, material, reason or method in new situations. The practical (carrying out grafting) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the tool","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_CARE', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS', 'agriculture', 9, 'Say how a grafted plant is cared for until the union succeeds', ARRAY['AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.c']::text[], 'Says how a grafted plant is cared for: water it, keep it in light shade, protect the union from knocks and animals, remove shoots growing from the rootstock below the union, remove the tape once the union has healed (about 6 to 8 weeks), and watch for the scion to sprout; in the app the child picks the right step, order, material, reason or method in new situations. The practical (caring for grafted plants until the union succeeds) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the action","order the steps","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_PURPOSES', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS', 'agriculture', 9, 'Appraise grafting for repair, aesthetics, improvement and rejuvenation', ARRAY['AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.d']::text[], 'Appraises the purposes of grafting (repairing a damaged plant, aesthetics such as several colours on one plant, improvement such as early fruiting and better fruit on a hardy rootstock, rejuvenating an old tree by topworking) and judges which purpose fits a given case, and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["match purpose and case","story","choose the best"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER', 'agriculture', 9, 'Describe how a homemade sun dryer for vegetables is made and how it works', ARRAY['AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.a']::text[], 'Describes a homemade sun dryer: a box with a clear cover that lets sunlight in and traps heat, a black inside that absorbs heat, mesh trays for the vegetables, air inlets low and outlets high so warm air carries moisture away, raised off the ground, from local materials, and gives the reason in a new situation; in the app the child picks the right answer in new situations. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the part","choose the material","story with a reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER', 'agriculture', 9, 'Say how a sun dryer is built, placed and used to dry vegetables', ARRAY['AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.b']::text[], 'Says how a sun dryer is built and used: sketch and measure, build the box and trays, fit the clear cover and air holes, face it to the sun, raised and tilted, load washed thinly sliced vegetables in one layer, close it, turn the produce, take it out when crisp, store it sealed, and clean the dryer; in the app the child picks the right step, order, material, reason or method in new situations. The practical (constructing a homemade sun dryer and drying vegetables in it) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the place","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_REARING', 'skill', 'essential', 'Feeding animals every day (Grade 8) is why feed must be kept for dry months. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
