INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_MODES', 'skill', 'essential', 'Radiation, conduction and convection (Science Grade 5) explain how the dryer heats and moves air. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN', 'skill', 'essential', 'The child knows how the dryer works before building and using it. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE', 'skill', 'essential', 'Measuring and marking out (Pre-Technical Grade 7) come before building. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS.M_AG9_HM_RAINY', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS', 'Thinks feed is conserved during the drought, when grass is short.', '{"question":"When should forage be conserved for a drought?","wrong_answer":"During the drought","correct_answer":"In the rainy season when there is plenty of grass"}'::jsonb, 'The child thinks of acting when the problem is seen.', 'Offer "During the drought" next to the right answer and ask the question again in a new context.', 'Show a calendar: grass is plenty in April and gone in September.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS.M_AG9_HM_STANDING', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS', 'Thinks standing forage means grass cut and stood in heaps.', '{"question":"What is standing forage?","wrong_answer":"Grass cut and stood in heaps","correct_answer":"Grass left uncut in a fenced paddock to be grazed in the dry season"}'::jsonb, 'The child pictures "standing" as stacked.', 'Offer "Grass cut and stood in heaps" next to the right answer and ask the question again in a new context.', 'Show a fenced paddock left ungrazed in the rains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS.M_AG9_HM_STOVER', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS', 'Burns maize stover after harvest instead of keeping it as feed.', '{"question":"What can be done with maize stover after harvest to help in a drought?","wrong_answer":"Burn it to clear the shamba","correct_answer":"Store it dry as animal feed"}'::jsonb, 'Burning is the usual way to clear fields.', 'Offer "Burn it to clear the shamba" next to the right answer and ask the question again in a new context.', 'Ask what cattle eat when the grass is gone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS.M_AG9_HM_LOSS', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAY_METHODS', 'Thinks animals can always be moved to find grass, so there is no need to conserve feed.', '{"question":"Why is conserving feed better than moving animals in a drought?","wrong_answer":"Moving is always better","correct_answer":"Moving is far, costly and risky; stored feed keeps animals strong at home"}'::jsonb, 'The child has heard of herders moving with animals.', 'Offer "Moving is always better" next to the right answer and ask the question again in a new context.', 'Discuss the losses of animals in the last drought.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAYMAKING.M_AG9_HK_LATE', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAYMAKING', 'Cuts grass for hay when it is old, dry and brown.', '{"question":"When is grass best cut for hay?","wrong_answer":"When it is old, dry and brown","correct_answer":"At flowering, when it is still green and leafy"}'::jsonb, 'The child thinks dry grass is already hay.', 'Offer "When it is old, dry and brown" next to the right answer and ask the question again in a new context.', 'Compare green leafy grass and old brown stems: which would a cow choose?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAYMAKING.M_AG9_HK_OPEN', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAYMAKING', 'Leaves bales out in the open after making them.', '{"question":"Where are hay bales kept after baling?","wrong_answer":"Out in the field","correct_answer":"Under a roof or cover, off the ground"}'::jsonb, 'The child thinks dry hay stays dry.', 'Offer "Out in the field" next to the right answer and ask the question again in a new context.', 'Show a bale left out in rain: black and mouldy inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAYMAKING.M_AG9_HK_WET', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAYMAKING', 'Bales or stacks the grass while it is still wet.', '{"question":"What happens if hay is baled while still damp?","wrong_answer":"It keeps better","correct_answer":"It goes mouldy and can heat up"}'::jsonb, 'The child wants to finish quickly.', 'Offer "It keeps better" next to the right answer and ask the question again in a new context.', 'Smell a damp bale left for a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAYMAKING.M_AG9_HK_GROUND', 'AGRI.G9.CONSER.CONSERVING_ANIMAL_FEED_H.HAYMAKING', 'Stacks hay straight on the ground with a flat top.', '{"question":"How should a hay stack be built?","wrong_answer":"On the ground with a flat top","correct_answer":"On a raised base with a sloping, covered top"}'::jsonb, 'The child does not think about damp from below and rain from above.', 'Offer "On the ground with a flat top" next to the right answer and ask the question again in a new context.', 'Pour water on a flat-topped and a sloping model stack.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_WHY.M_AG9_LW_OPEN', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_WHY', 'Leaves leftover food uncovered in the warm pot overnight.', '{"question":"How should leftover food be kept overnight?","wrong_answer":"In the warm pot, uncovered","correct_answer":"Cooled quickly, covered and kept in a cool place"}'::jsonb, 'The child thinks cooked food is safe whatever happens.', 'Offer "In the warm pot, uncovered" next to the right answer and ask the question again in a new context.', 'Ask what flies and warmth do to food overnight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_WHY.M_AG9_LW_SMELL', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_WHY', 'Thinks food that smells fine is always safe.', '{"question":"Leftover rice has been out all day in the heat but smells fine. Is it safe?","wrong_answer":"Yes, it smells fine","correct_answer":"No, germs may have grown without changing the smell"}'::jsonb, 'The child trusts the nose.', 'Offer "Yes, it smells fine" next to the right answer and ask the question again in a new context.', 'Explain some food-poisoning germs give no smell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_WHY.M_AG9_LW_WASTE', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_WHY', 'Thinks leftovers are rubbish to be thrown away.', '{"question":"Why conserve leftover food?","wrong_answer":"There is no reason","correct_answer":"It saves food and money and cuts waste"}'::jsonb, 'The child sees leftovers as scraps.', 'Offer "There is no reason" next to the right answer and ask the question again in a new context.', 'Add up the cost of food thrown away in a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_WHY.M_AG9_LW_DAYS', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_WHY', 'Keeps leftovers for many days without a fridge.', '{"question":"How long can leftovers be kept without a fridge?","wrong_answer":"A week","correct_answer":"Until the next meal or next day only"}'::jsonb, 'The child thinks cooked food lasts like dry food.', 'Offer "A week" next to the right answer and ask the question again in a new context.', 'Show mould on githeri kept for three days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_PREP.M_AG9_LP_WARM', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_PREP', 'Warms leftovers only until lukewarm.', '{"question":"How hot should reheated leftovers be?","wrong_answer":"Just warm","correct_answer":"Steaming hot all the way through"}'::jsonb, 'The child heats until it is nice to eat.', 'Offer "Just warm" next to the right answer and ask the question again in a new context.', 'Explain heat must reach the middle to kill germs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_PREP.M_AG9_LP_MIXOLD', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_PREP', 'Mixes old leftovers with freshly cooked food to use them up.', '{"question":"Should yesterday''s leftovers be stirred into today''s fresh stew?","wrong_answer":"Yes, it saves food","correct_answer":"No, keep them apart and use the leftovers first, reheated once"}'::jsonb, 'The child thinks mixing hides the old food safely.', 'Offer "Yes, it saves food" next to the right answer and ask the question again in a new context.', 'Explain germs in the old food spread through the whole pot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_PREP.M_AG9_LP_TWICE', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_PREP', 'Reheats the same leftovers again and again.', '{"question":"How many times should leftovers be reheated?","wrong_answer":"As many times as needed","correct_answer":"Once only"}'::jsonb, 'The child thinks heating always makes food safe.', 'Offer "As many times as needed" next to the right answer and ask the question again in a new context.', 'Explain each cooling and warming lets germs grow again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_PREP.M_AG9_LP_RECIPE', 'AGRI.G9.CONSER.CONSERVING_LEFTOVER_FOOD.LEFTOVER_PREP', 'Thinks leftovers can only be reheated, never made into something new.', '{"question":"What new dish can be made from leftover rice?","wrong_answer":"None, only reheating","correct_answer":"Fried rice or rice pudding"}'::jsonb, 'The child has seen leftovers only warmed up.', 'Offer "None, only reheating" next to the right answer and ask the question again in a new context.', 'Make fried rice with leftover rice and vegetables.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_PARTS.M_AG9_IP_MIXED', 'AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_PARTS', 'Thinks integrated farming is any farm that keeps several things with no links between them.', '{"question":"What makes a farm \"integrated\"?","wrong_answer":"Keeping many things, each on its own","correct_answer":"The parts feed each other: one part''s waste is another''s input"}'::jsonb, 'The child takes "integrated" to mean "many".', 'Offer "Keeping many things, each on its own" next to the right answer and ask the question again in a new context.', 'Draw arrows between the parts of a farm; a farm with no arrows is not integrated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_PARTS.M_AG9_IP_DUNG', 'AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_PARTS', 'Thinks animal droppings are waste with no use on the farm.', '{"question":"How can rabbit droppings be used in integrated farming?","wrong_answer":"They are waste","correct_answer":"To feed fish in the pond or manure the vegetables"}'::jsonb, 'The child sees droppings as dirt.', 'Offer "They are waste" next to the right answer and ask the question again in a new context.', 'Show a hutch built over a fish pond.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_PARTS.M_AG9_IP_POND', 'AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_PARTS', 'Thinks fish pond water is useless for crops.', '{"question":"How can water from a fish pond help the garden?","wrong_answer":"It cannot","correct_answer":"It is rich in nutrients and waters the vegetables"}'::jsonb, 'The child thinks pond water is dirty.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Water two beds, one with pond water, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_PARTS.M_AG9_IP_LAND', 'AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_PARTS', 'Thinks integrated farming needs more land than one enterprise.', '{"question":"Why does integrated farming suit a small plot?","wrong_answer":"It does not; it needs more land","correct_answer":"The parts share space and inputs, so a small plot gives more"}'::jsonb, 'The child thinks more activities need more land.', 'Offer "It does not; it needs more land" next to the right answer and ask the question again in a new context.', 'Show a small plot plan with a pond, hutch, poultry and beds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_MODEL.M_AG9_IM_ARROW', 'AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_MODEL', 'Draws arrows the wrong way, such as from the fish pond to the rabbits.', '{"question":"In a model, which way does the arrow go between the rabbit hutch and the fish pond?","wrong_answer":"From the pond to the hutch","correct_answer":"From the hutch to the pond (droppings feed the fish)"}'::jsonb, 'The child draws arrows without asking what moves.', 'Offer "From the pond to the hutch" next to the right answer and ask the question again in a new context.', 'Ask what moves from one to the other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_MODEL.M_AG9_IM_LABEL', 'AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_MODEL', 'Builds the model with no labels or key.', '{"question":"Why label the parts of an integrated farming model?","wrong_answer":"It is not needed","correct_answer":"So others can see each component and the links between them"}'::jsonb, 'The child thinks the model explains itself.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Ask a visitor to explain an unlabelled model.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_MODEL.M_AG9_IM_PLACE', 'AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_MODEL', 'Places the compost pit far from the garden in the model.', '{"question":"Where is the compost pit best placed in an integrated plot?","wrong_answer":"Far from the garden","correct_answer":"Near the garden and the animal houses"}'::jsonb, 'The child does not think about carrying work.', 'Offer "Far from the garden" next to the right answer and ask the question again in a new context.', 'Count the steps to carry compost across the plot model.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_MODEL.M_AG9_IM_SKETCH', 'AGRI.G9.CONSER.INTEGRATED_FARMING.INTEGRATED_MODEL', 'Builds the model without a sketch, so parts do not fit.', '{"question":"What is done before building the model?","wrong_answer":"Start building at once","correct_answer":"Sketch the plot and plan where each part goes"}'::jsonb, 'The child is keen to build.', 'Offer "Start building at once" next to the right answer and ask the question again in a new context.', 'Show a model where the pond covers the garden.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_PRACTICES.M_AG9_OP_NOTHING', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_PRACTICES', 'Thinks organic gardening means doing nothing: no manure, no pest control.', '{"question":"What does organic gardening mean?","wrong_answer":"Growing with no inputs or care at all","correct_answer":"Growing with natural inputs such as compost and organic sprays, not synthetic chemicals"}'::jsonb, 'The child hears "natural" as "left alone".', 'Offer "Growing with no inputs or care at all" next to the right answer and ask the question again in a new context.', 'Compare an organic bed (compost, care) with an untended one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_PRACTICES.M_AG9_OP_YIELD', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_PRACTICES', 'Thinks organic crops cannot grow well at all.', '{"question":"Can an organic garden give a good harvest?","wrong_answer":"No, never","correct_answer":"Yes, with good compost, foliar feeds and care"}'::jsonb, 'The child has heard that chemicals are needed for big harvests.', 'Offer "No, never" next to the right answer and ask the question again in a new context.', 'Show the class organic bed at harvest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_PRACTICES.M_AG9_OP_HEALTH', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_PRACTICES', 'Thinks food grown with chemicals and organic food are no different for health or soil.', '{"question":"Why do people choose organic food?","wrong_answer":"There is no difference","correct_answer":"No harmful chemical residues, and the soil and water stay healthy"}'::jsonb, 'The child cannot see residues and assumes none.', 'Offer "There is no difference" next to the right answer and ask the question again in a new context.', 'Read a pesticide label''s waiting period before harvest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_PRACTICES.M_AG9_OP_ROTATE', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_PRACTICES', 'Thinks crop rotation is not part of organic gardening.', '{"question":"Why is crop rotation used in organic gardening?","wrong_answer":"It is not used","correct_answer":"It breaks the life of pests and diseases without chemicals"}'::jsonb, 'The child links pest control only with spraying.', 'Offer "It is not used" next to the right answer and ask the question again in a new context.', 'Recall Grade 8: rotation stops soil pests building up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_INPUTS.M_AG9_OI_STRONG', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_INPUTS', 'Sprays the foliar feed without diluting it.', '{"question":"How is Mexican sunflower liquid feed used?","wrong_answer":"Poured on undiluted","correct_answer":"Diluted with water before spraying or watering"}'::jsonb, 'The child thinks stronger is better.', 'Offer "Poured on undiluted" next to the right answer and ask the question again in a new context.', 'Compare leaves sprayed with strong and diluted feed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_INPUTS.M_AG9_OI_SOAK', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_INPUTS', 'Uses the Mexican sunflower soak the next day.', '{"question":"How long is a plant or manure liquid feed left to soak?","wrong_answer":"One day","correct_answer":"About two weeks, stirred now and then"}'::jsonb, 'The child expects quick results.', 'Offer "One day" next to the right answer and ask the question again in a new context.', 'Compare the colour of a one-day and a two-week soak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_INPUTS.M_AG9_OI_NOON', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_INPUTS', 'Sprays organic pesticides in the hot midday sun.', '{"question":"When is the best time to spray an organic pesticide?","wrong_answer":"At midday","correct_answer":"Early morning or evening"}'::jsonb, 'The child sees no difference between times.', 'Offer "At midday" next to the right answer and ask the question again in a new context.', 'Explain sun breaks down the spray and burns wet leaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_INPUTS.M_AG9_OI_FRESHMANURE', 'AGRI.G9.FOOD_P.ORGANIC_GARDENING.ORGANIC_INPUTS', 'Puts fresh animal manure straight on the crops.', '{"question":"What kind of manure is used on an organic garden?","wrong_answer":"Fresh manure straight from the shed","correct_answer":"Well-rotted manure or compost"}'::jsonb, 'The child thinks manure is manure.', 'Offer "Fresh manure straight from the shed" next to the right answer and ask the question again in a new context.', 'Show seedlings scorched by fresh manure.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_PREP.M_AG9_SP_CRACKS', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_PREP', 'Leaves cracks in the store walls because they are small.', '{"question":"Why are cracks in a store sealed before storing?","wrong_answer":"Small cracks do not matter","correct_answer":"Weevils and other pests hide and breed in cracks"}'::jsonb, 'The child thinks only big holes let pests in.', 'Offer "Small cracks do not matter" next to the right answer and ask the question again in a new context.', 'Scrape out an old crack and find weevils.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_PREP.M_AG9_SP_ROOF', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_PREP', 'Stores the produce before fixing a leaking roof.', '{"question":"What is done about a leaking store roof?","wrong_answer":"Store first and fix later","correct_answer":"Repair it before storing"}'::jsonb, 'The child thinks the produce will stay dry in sacks.', 'Offer "Store first and fix later" next to the right answer and ask the question again in a new context.', 'Show mouldy grain under a roof leak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_PREP.M_AG9_SP_RAT', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_PREP', 'Thinks rat guards and clean surroundings are not needed if there is a cat.', '{"question":"Why fit rat guards on granary legs?","wrong_answer":"A cat is enough","correct_answer":"So rats cannot climb into the store"}'::jsonb, 'The child trusts one method.', 'Offer "A cat is enough" next to the right answer and ask the question again in a new context.', 'Show a granary leg with and without a metal guard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_PREP.M_AG9_SP_BAGS', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_PREP', 'Reuses old sacks without cleaning or checking them.', '{"question":"What is done with old storage bags before reuse?","wrong_answer":"Use them as they are","correct_answer":"Shake out, clean, dry and check for holes and pests"}'::jsonb, 'The child sees an empty sack as clean.', 'Offer "Use them as they are" next to the right answer and ask the question again in a new context.', 'Turn an old sack inside out to find weevils in the seams.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_MANAGE.M_AG9_SM_FORGET', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_MANAGE', 'Thinks produce once stored needs no more checking.', '{"question":"How often should stored grain be checked?","wrong_answer":"Never, once it is stored","correct_answer":"Regularly, every week or two"}'::jsonb, 'The child thinks storage is the end of the job.', 'Offer "Never, once it is stored" next to the right answer and ask the question again in a new context.', 'Show grain that spoiled unseen in a month.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_MANAGE.M_AG9_SM_HEAT', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_MANAGE', 'Thinks a warm patch in stored grain is normal.', '{"question":"A farmer finds warm grain in the middle of a sack. What does it mean?","wrong_answer":"It is normal","correct_answer":"Damp or pests are spoiling it; dry and check it"}'::jsonb, 'The child does not know spoiling grain heats up.', 'Offer "It is normal" next to the right answer and ask the question again in a new context.', 'Push a hand into damp grain left for a week (teacher''s demonstration).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_MANAGE.M_AG9_SM_SPOILT', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_MANAGE', 'Leaves spoilt produce among the good to avoid waste.', '{"question":"What is done with mouldy maize found in the store?","wrong_answer":"Leave it with the rest","correct_answer":"Remove it and dispose of it away from the store"}'::jsonb, 'The child does not want to waste anything.', 'Offer "Leave it with the rest" next to the right answer and ask the question again in a new context.', 'Explain mould spreads, and mouldy maize can be poisonous (aflatoxin).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_MANAGE.M_AG9_SM_AIR', 'AGRI.G9.FOOD_P.STORAGE_OF_CROP_PRODUCE.STORE_MANAGE', 'Closes up the store completely so no air enters.', '{"question":"Why must a store with sacks be ventilated?","wrong_answer":"Closed is better","correct_answer":"Moving air keeps the produce dry and cool"}'::jsonb, 'The child thinks closed keeps pests out.', 'Offer "Closed is better" next to the right answer and ask the question again in a new context.', 'Compare damp in a closed and an airy room.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_MIXTURES.M_AG9_FM_SWAP', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_MIXTURES', 'Calls chapati mixture a batter and pancake mixture a dough.', '{"question":"Is chapati made from a batter or a dough?","wrong_answer":"A batter","correct_answer":"A dough"}'::jsonb, 'The child knows both words but not which is runny.', 'Offer "A batter" next to the right answer and ask the question again in a new context.', 'Show a runny batter poured and a stiff dough rolled.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_MIXTURES.M_AG9_FM_RATIO', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_MIXTURES', 'Thinks a batter has more flour than liquid.', '{"question":"Which has more liquid than flour?","wrong_answer":"A dough","correct_answer":"A batter"}'::jsonb, 'The child does not link runniness with the amount of liquid.', 'Offer "A dough" next to the right answer and ask the question again in a new context.', 'Measure the liquid and flour for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_MIXTURES.M_AG9_FM_MANDAZI', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_MIXTURES', 'Thinks mandazi is made from a batter because it is fried.', '{"question":"What mixture are mandazi made from?","wrong_answer":"A batter, because they are fried","correct_answer":"A soft dough that is rolled and cut"}'::jsonb, 'The child names the mixture from the cooking method.', 'Offer "A batter, because they are fried" next to the right answer and ask the question again in a new context.', 'Show mandazi dough rolled and cut before frying.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_MIXTURES.M_AG9_FM_ONLY', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_MIXTURES', 'Thinks only wheat flour makes flour mixtures.', '{"question":"Can other flours make flour mixtures?","wrong_answer":"No, only wheat flour","correct_answer":"Yes, such as maize, millet, sorghum or cassava flour in some recipes"}'::jsonb, 'The child has seen only wheat flour in chapati and mandazi.', 'Offer "No, only wheat flour" next to the right answer and ask the question again in a new context.', 'Show millet pancakes or cassava flour recipes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.MIXTURE_PREP.M_AG9_MP_ALLWATER', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.MIXTURE_PREP', 'Pours all the liquid into the flour at once.', '{"question":"How is liquid added to flour for a dough?","wrong_answer":"All at once","correct_answer":"A little at a time while mixing"}'::jsonb, 'The child wants to finish quickly.', 'Offer "All at once" next to the right answer and ask the question again in a new context.', 'Pour all the water into a cup of flour: it turns to sticky paste.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.MIXTURE_PREP.M_AG9_MP_KNEAD', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.MIXTURE_PREP', 'Skips kneading the chapati dough.', '{"question":"Why is chapati dough kneaded?","wrong_answer":"It does not need it","correct_answer":"To make it smooth and stretchy so the chapati is soft"}'::jsonb, 'The child thinks mixing is enough.', 'Offer "It does not need it" next to the right answer and ask the question again in a new context.', 'Roll an unkneaded and a kneaded dough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.MIXTURE_PREP.M_AG9_MP_LUMPS', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.MIXTURE_PREP', 'Leaves lumps in the pancake batter.', '{"question":"How is a smooth batter made?","wrong_answer":"Stir once and leave the lumps","correct_answer":"Sift the flour and add liquid gradually while beating"}'::jsonb, 'The child thinks lumps cook out.', 'Offer "Stir once and leave the lumps" next to the right answer and ask the question again in a new context.', 'Fry a lumpy pancake and a smooth one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.MIXTURE_PREP.M_AG9_MP_NOMEASURE', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.MIXTURE_PREP', 'Guesses the amounts instead of measuring.', '{"question":"Why are ingredients measured for a batter?","wrong_answer":"Guessing is fine","correct_answer":"The right amounts give the right thickness every time"}'::jsonb, 'The child has seen adults cook without measuring.', 'Offer "Guessing is fine" next to the right answer and ask the question again in a new context.', 'Make two batters, one guessed and one measured, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_PRODUCTS.M_AG9_FP_COLDPAN', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_PRODUCTS', 'Pours pancake batter into a cold pan.', '{"question":"When is pancake batter poured into the pan?","wrong_answer":"Into a cold pan","correct_answer":"When the greased pan is hot"}'::jsonb, 'The child does not see why heat matters at the start.', 'Offer "Into a cold pan" next to the right answer and ask the question again in a new context.', 'Pour batter into a cold pan: it sticks and stays pale.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_PRODUCTS.M_AG9_FP_TURN', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_PRODUCTS', 'Turns the pancake before the bubbles burst.', '{"question":"When is a pancake turned?","wrong_answer":"At once","correct_answer":"When bubbles appear and burst and the edges set"}'::jsonb, 'The child turns too early to avoid burning.', 'Offer "At once" next to the right answer and ask the question again in a new context.', 'Watch the bubbles in the demonstration.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_PRODUCTS.M_AG9_FP_THICK', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_PRODUCTS', 'Rolls chapati thick so it is filling.', '{"question":"Why is chapati rolled thin?","wrong_answer":"Thick is better","correct_answer":"So it cooks through and stays soft"}'::jsonb, 'The child thinks thick gives more food.', 'Offer "Thick is better" next to the right answer and ask the question again in a new context.', 'Cook a thick and a thin chapati.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_PRODUCTS.M_AG9_FP_OILTEMP', 'AGRI.G9.FOOD_P.COOKING_USING_FLOUR_MIXT.FLOUR_PRODUCTS', 'Fries mandazi in oil that is not yet hot.', '{"question":"Why must oil be hot before frying mandazi?","wrong_answer":"It does not matter","correct_answer":"In cool oil mandazi soak up oil and go greasy"}'::jsonb, 'The child does not link oil heat with greasiness.', 'Offer "It does not matter" next to the right answer and ask the question again in a new context.', 'Recall Grade 5: food in cold oil is soggy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_WHY.M_AG9_WF_DRAIN', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_WHY', 'Thinks an open drain cleans itself when it rains.', '{"question":"Why must open drains be cleared?","wrong_answer":"Rain cleans them","correct_answer":"Blocked drains hold dirty water that breeds mosquitoes and floods"}'::jsonb, 'The child pictures rain washing everything away.', 'Offer "Rain cleans them" next to the right answer and ask the question again in a new context.', 'Show a blocked drain with standing water after rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_WHY.M_AG9_WF_LID', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_WHY', 'Thinks a bin is fine without a lid.', '{"question":"Why should a dustbin have a lid?","wrong_answer":"It does not need one","correct_answer":"To keep out flies, rats and rain and keep smells in"}'::jsonb, 'The child sees the bin as a box for rubbish only.', 'Offer "It does not need one" next to the right answer and ask the question again in a new context.', 'Compare an open and a covered bin after a day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_WHY.M_AG9_WF_DISEASE', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_WHY', 'Thinks dirty bins and drains cause only bad smells, not disease.', '{"question":"Which disease can spread from dirty drains and bins?","wrong_answer":"None, they only smell","correct_answer":"Cholera, typhoid or malaria"}'::jsonb, 'The child links dirt with smell, not germs.', 'Offer "None, they only smell" next to the right answer and ask the question again in a new context.', 'Trace how a fly goes from a bin to food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_WHY.M_AG9_WF_SINK', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_WHY', 'Pours food scraps and cooking fat down the sink.', '{"question":"Why should fat and food scraps not go down the sink?","wrong_answer":"They wash away","correct_answer":"They block the pipe, smell and attract pests"}'::jsonb, 'The child thinks water carries everything away.', 'Offer "They wash away" next to the right answer and ask the question again in a new context.', 'Show a pipe blocked with hardened fat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_CLEAN.M_AG9_WC_HANDS', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_CLEAN', 'Cleans a bin with bare hands and does not wash after.', '{"question":"What should you wear to clean a dustbin?","wrong_answer":"Nothing special","correct_answer":"Gloves and an apron, and wash hands after"}'::jsonb, 'The child does not see the bin as a germ source.', 'Offer "Nothing special" next to the right answer and ask the question again in a new context.', 'Recall protective clothing from Grade 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_CLEAN.M_AG9_WC_WET', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_CLEAN', 'Puts the bin back wet with the lid closed.', '{"question":"What is done after washing a bin?","wrong_answer":"Close it wet","correct_answer":"Dry it in the sun with the lid open"}'::jsonb, 'The child wants to finish quickly.', 'Offer "Close it wet" next to the right answer and ask the question again in a new context.', 'Smell a bin closed wet for two days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_CLEAN.M_AG9_WC_SILT', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_CLEAN', 'Shovels silt from the drain onto its edge, where rain washes it back.', '{"question":"Where does silt removed from a drain go?","wrong_answer":"On the edge of the drain","correct_answer":"Away from the drain, to a safe place"}'::jsonb, 'The child thinks the job is done once the drain is clear.', 'Offer "On the edge of the drain" next to the right answer and ask the question again in a new context.', 'Show silt washed back into a drain after rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_CLEAN.M_AG9_WC_STRAINER', 'AGRI.G9.HYGIEN.CLEANING_WASTE_DISPOSAL_.WASTE_FACILITY_CLEAN', 'Never clears the sink strainer.', '{"question":"How is a sink kept clean daily?","wrong_answer":"Rinse it only","correct_answer":"Empty the strainer into the bin and scrub the sink"}'::jsonb, 'The child cleans only what is seen.', 'Offer "Rinse it only" next to the right answer and ask the question again in a new context.', 'Lift a strainer full of old food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_METHODS.M_AG9_DM_CLEAN', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_METHODS', 'Thinks a clean-looking article is free of germs.', '{"question":"A towel looks clean. Is it free of germs?","wrong_answer":"Yes, it looks clean","correct_answer":"Not always; germs cannot be seen, so it may need disinfecting"}'::jsonb, 'The child trusts the eye.', 'Offer "Yes, it looks clean" next to the right answer and ask the question again in a new context.', 'Recall hand washing: germs cannot be seen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_METHODS.M_AG9_DM_BOILALL', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_METHODS', 'Thinks every article can be boiled.', '{"question":"Can a coloured nylon item be boiled to disinfect it?","wrong_answer":"Yes, boil everything","correct_answer":"No, boil white cotton only; use sun or ironing for others"}'::jsonb, 'The child thinks one method fits all.', 'Offer "Yes, boil everything" next to the right answer and ask the question again in a new context.', 'Show a coloured item faded and shrunk by boiling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_METHODS.M_AG9_DM_SUN', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_METHODS', 'Thinks sunlight only dries clothes and does not disinfect.', '{"question":"How does drying in strong sun help hygiene?","wrong_answer":"It only dries","correct_answer":"The sun''s rays help kill germs"}'::jsonb, 'The child sees the sun only as a dryer.', 'Offer "It only dries" next to the right answer and ask the question again in a new context.', 'Explain the sun''s ultraviolet rays kill many germs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_METHODS.M_AG9_DM_IRON', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_METHODS', 'Thinks ironing is only to remove creases.', '{"question":"How does ironing help hygiene?","wrong_answer":"It only removes creases","correct_answer":"The heat helps kill germs and lice eggs"}'::jsonb, 'The child sees ironing as looks only.', 'Offer "It only removes creases" next to the right answer and ask the question again in a new context.', 'Talk about ironing school uniforms against lice and germs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_PRACTICE.M_AG9_DP_DIRTY', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_PRACTICE', 'Disinfects an article before washing it.', '{"question":"What is done before disinfecting a towel?","wrong_answer":"Nothing, disinfect it as it is","correct_answer":"Wash it clean first"}'::jsonb, 'The child thinks the disinfectant does all the work.', 'Offer "Nothing, disinfect it as it is" next to the right answer and ask the question again in a new context.', 'Recall Grade 7: disinfectant works only on a clean surface.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_PRACTICE.M_AG9_DP_STRONG', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_PRACTICE', 'Uses chemical disinfectant undiluted to make it stronger.', '{"question":"How is a chemical disinfectant used on clothes?","wrong_answer":"Undiluted, as strong as possible","correct_answer":"Diluted as the label says, by an adult, then rinsed out"}'::jsonb, 'The child thinks stronger is better.', 'Offer "Undiluted, as strong as possible" next to the right answer and ask the question again in a new context.', 'Read a disinfectant label''s dilution and warnings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_PRACTICE.M_AG9_DP_SHORT', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_PRACTICE', 'Boils handkerchiefs for a minute only.', '{"question":"How long are white cotton handkerchiefs boiled to disinfect them?","wrong_answer":"A minute","correct_answer":"About 10 to 15 minutes"}'::jsonb, 'The child thinks boiling water kills germs at once.', 'Offer "A minute" next to the right answer and ask the question again in a new context.', 'Explain heat needs time to kill germs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_PRACTICE.M_AG9_DP_SHADE', 'AGRI.G9.HYGIEN.DISINFECTING_CLOTHING_AN.DISINFECT_PRACTICE', 'Dries disinfected articles in a damp, shaded corner.', '{"question":"Where are disinfected towels dried?","wrong_answer":"In a damp shaded corner","correct_answer":"In full sun where air moves"}'::jsonb, 'The child dries where there is space.', 'Offer "In a damp shaded corner" next to the right answer and ask the question again in a new context.', 'Smell a towel dried in a damp corner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_MEANING.M_AG9_GM_SWAP', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_MEANING', 'Calls the rootstock the scion and the scion the rootstock.', '{"question":"In a graft, which part gives the roots?","wrong_answer":"The scion","correct_answer":"The rootstock"}'::jsonb, 'The two new words are learnt together.', 'Offer "The scion" next to the right answer and ask the question again in a new context.', 'Label a grafted seedling: root (rootstock) at the bottom, shoot (scion) on top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_MEANING.M_AG9_GM_ANY', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_MEANING', 'Thinks any two plants can be grafted, such as a mango scion on a bean.', '{"question":"Can a mango scion be grafted onto an avocado rootstock?","wrong_answer":"Yes, any plants join","correct_answer":"No, they must be the same or closely related kind"}'::jsonb, 'The child thinks tape holds anything together.', 'Offer "Yes, any plants join" next to the right answer and ask the question again in a new context.', 'Explain the tissues must match to grow as one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_MEANING.M_AG9_GM_SEED', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_MEANING', 'Thinks a grafted tree is grown from a seed of the good tree.', '{"question":"How is a grafted mango different from one grown from seed?","wrong_answer":"It is the same","correct_answer":"It carries the good parent''s fruit exactly and fruits sooner"}'::jsonb, 'The child thinks all trees come from seed.', 'Offer "It is the same" next to the right answer and ask the question again in a new context.', 'Compare seedling mangoes (mixed fruit) with grafted ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_MEANING.M_AG9_GM_UNION', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_MEANING', 'Thinks the union is the tape.', '{"question":"What is the graft union?","wrong_answer":"The grafting tape","correct_answer":"The place where the scion and rootstock grow together"}'::jsonb, 'The child sees the tape at the join.', 'Offer "The grafting tape" next to the right answer and ask the question again in a new context.', 'Show a healed union after the tape is off.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_STEPS.M_AG9_GS_CAMBIUM', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_STEPS', 'Fits the cut pieces without matching the green layer under the bark.', '{"question":"What must touch for a graft to take?","wrong_answer":"Any part of the cuts","correct_answer":"The green cambium layers of scion and rootstock"}'::jsonb, 'The child sees only the wood.', 'Offer "Any part of the cuts" next to the right answer and ask the question again in a new context.', 'Show the thin green ring under the bark in a cut stem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_STEPS.M_AG9_GS_BLUNT', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_STEPS', 'Uses a blunt or dirty knife.', '{"question":"Why is a sharp, clean knife used for grafting?","wrong_answer":"Any knife works","correct_answer":"Clean smooth cuts heal and join; dirty knives carry disease"}'::jsonb, 'The child thinks cutting is cutting.', 'Offer "Any knife works" next to the right answer and ask the question again in a new context.', 'Compare a smooth cut and a torn cut on a stem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_STEPS.M_AG9_GS_LOOSE', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_STEPS', 'Wraps the graft loosely.', '{"question":"How is the graft wrapped?","wrong_answer":"Loosely","correct_answer":"Firmly with grafting tape so the cuts stay together and dry"}'::jsonb, 'The child fears hurting the plant.', 'Offer "Loosely" next to the right answer and ask the question again in a new context.', 'Show a loose graft that slipped apart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_STEPS.M_AG9_GS_DRY', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_STEPS', 'Leaves the cut scion in the sun before grafting.', '{"question":"What happens if a scion dries before grafting?","wrong_answer":"Nothing","correct_answer":"It dies and the graft fails"}'::jsonb, 'The child does not know the scion is alive.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Leave a cut scion in the sun for an hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_CARE.M_AG9_GC_SUCKERS', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_CARE', 'Leaves shoots growing from the rootstock below the union.', '{"question":"What is done with shoots growing below the graft union?","wrong_answer":"Leave them to grow","correct_answer":"Remove them so the scion gets the food"}'::jsonb, 'The child thinks all growth is good.', 'Offer "Leave them to grow" next to the right answer and ask the question again in a new context.', 'Show a graft where rootstock shoots took over.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_CARE.M_AG9_GC_TAPE', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_CARE', 'Leaves the grafting tape on for ever.', '{"question":"When is the grafting tape removed?","wrong_answer":"Never","correct_answer":"After the union has healed, about 6 to 8 weeks"}'::jsonb, 'The child thinks the tape protects the plant.', 'Offer "Never" next to the right answer and ask the question again in a new context.', 'Show a stem strangled by tape left on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_CARE.M_AG9_GC_SUN', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_CARE', 'Puts the newly grafted plant in full sun with no water.', '{"question":"Where is a new graft kept?","wrong_answer":"In full sun, unwatered","correct_answer":"In light shade, watered regularly"}'::jsonb, 'The child thinks a tree is tough.', 'Offer "In full sun, unwatered" next to the right answer and ask the question again in a new context.', 'Compare grafts in shade and sun after a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_CARE.M_AG9_GC_KNOCK', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_CARE', 'Lets animals and people brush against the union.', '{"question":"Why protect the graft union?","wrong_answer":"It is strong","correct_answer":"A knock can break the union before it heals"}'::jsonb, 'The child sees the tape as protection enough.', 'Offer "It is strong" next to the right answer and ask the question again in a new context.', 'Show a broken graft.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_PURPOSES.M_AG9_GP_REPAIR', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_PURPOSES', 'Thinks a tree with a damaged trunk must be cut down.', '{"question":"A young mango tree has its bark eaten by goats. What can grafting do?","wrong_answer":"Nothing, cut it down","correct_answer":"Bridge graft over the damage to repair it"}'::jsonb, 'The child does not know grafting repairs.', 'Offer "Nothing, cut it down" next to the right answer and ask the question again in a new context.', 'Show a bridge graft picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_PURPOSES.M_AG9_GP_OLD', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_PURPOSES', 'Thinks an old tree giving poor fruit must be replaced by a new seedling.', '{"question":"How can an old avocado tree with poor fruit be rejuvenated?","wrong_answer":"Cut it down and plant a seed","correct_answer":"Topwork it: cut back and graft a good variety on the old stump"}'::jsonb, 'The child thinks old trees cannot change.', 'Offer "Cut it down and plant a seed" next to the right answer and ask the question again in a new context.', 'Show a topworked tree fruiting in two years.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_PURPOSES.M_AG9_GP_LOOKS', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_PURPOSES', 'Thinks grafting is only for fruit, never for beauty.', '{"question":"Can grafting be used for beauty?","wrong_answer":"No, only for fruit","correct_answer":"Yes, such as several flower colours on one rose or bougainvillea"}'::jsonb, 'The child has seen grafting only in orchards.', 'Offer "No, only for fruit" next to the right answer and ask the question again in a new context.', 'Show a rose with two colours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_PURPOSES.M_AG9_GP_IMPROVE', 'AGRI.G9.PRODUC.GRAFTING_IN_PLANTS.GRAFT_PURPOSES', 'Thinks grafting makes the fruit bigger by itself, whatever the scion.', '{"question":"Why graft a good variety onto a hardy local rootstock?","wrong_answer":"The rootstock decides the fruit","correct_answer":"The scion gives the good fruit; the hardy rootstock gives strength and disease resistance"}'::jsonb, 'The child thinks the roots decide everything.', 'Offer "The rootstock decides the fruit" next to the right answer and ask the question again in a new context.', 'Compare fruit of the scion parent and the rootstock parent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN.M_AG9_SD_BLACK', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN', 'Paints the inside of the dryer white to keep it clean.', '{"question":"Why is the inside of a sun dryer black?","wrong_answer":"It makes no difference","correct_answer":"Black absorbs more heat from the sun"}'::jsonb, 'The child links white with clean.', 'Offer "It makes no difference" next to the right answer and ask the question again in a new context.', 'Leave a black and a white tin in the sun and feel them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN.M_AG9_SD_HOLES', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN', 'Seals the dryer completely with no air holes.', '{"question":"Why does a sun dryer need air holes at the bottom and top?","wrong_answer":"It should be sealed to keep heat in","correct_answer":"Warm moist air leaves at the top and dry air enters at the bottom"}'::jsonb, 'The child thinks trapping heat is all that matters.', 'Offer "It should be sealed to keep heat in" next to the right answer and ask the question again in a new context.', 'Show water drops forming inside a sealed box with wet leaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN.M_AG9_SD_COVER', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN', 'Uses a dark, opaque cover over the dryer.', '{"question":"What kind of cover does a sun dryer need?","wrong_answer":"A dark sheet that blocks the sun","correct_answer":"A clear polythene or glass cover that lets sunlight in"}'::jsonb, 'The child thinks a cover should shade the food.', 'Offer "A dark sheet that blocks the sun" next to the right answer and ask the question again in a new context.', 'Compare inside temperatures under clear and dark covers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN.M_AG9_SD_WHY', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_DESIGN', 'Thinks a sun dryer is no better than drying on a mat.', '{"question":"Why use a sun dryer instead of a mat on the ground?","wrong_answer":"There is no difference","correct_answer":"It dries faster and keeps out dust, flies, rain and animals"}'::jsonb, 'The child has seen open drying work.', 'Offer "There is no difference" next to the right answer and ask the question again in a new context.', 'Dry two lots of sukuma: dryer and mat; compare colour, dirt and time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE.M_AG9_SU_PILE', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE', 'Piles the vegetables thickly on the tray.', '{"question":"How are vegetables loaded in a sun dryer?","wrong_answer":"In a thick pile","correct_answer":"In one thin layer with space between pieces"}'::jsonb, 'The child wants to dry a lot at once.', 'Offer "In a thick pile" next to the right answer and ask the question again in a new context.', 'Load one tray thick and one thin; compare after a day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE.M_AG9_SU_SHADE', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE', 'Puts the dryer in the shade so the vegetables do not burn.', '{"question":"Where is a sun dryer placed?","wrong_answer":"In the shade","correct_answer":"In full sun, facing the sun, raised and tilted"}'::jsonb, 'The child fears the sun will cook the food.', 'Offer "In the shade" next to the right answer and ask the question again in a new context.', 'Measure how long drying takes in shade and in sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE.M_AG9_SU_CLEAN', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE', 'Never cleans the trays between batches.', '{"question":"Why clean the dryer trays after each batch?","wrong_answer":"There is no need","correct_answer":"Old bits grow mould and attract pests that spoil the next batch"}'::jsonb, 'The child thinks dry trays stay clean.', 'Offer "There is no need" next to the right answer and ask the question again in a new context.', 'Show mould on a tray left with old bits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE.M_AG9_SU_STORE', 'AGRI.G9.PRODUC.HOMEMADE_SUN_DRYER.SUN_DRYER_USE', 'Leaves the dried vegetables in the dryer for days after they are crisp.', '{"question":"What is done once the vegetables are crisp?","wrong_answer":"Leave them in the dryer","correct_answer":"Cool and store them in a sealed, dry container"}'::jsonb, 'The child thinks the dryer is a store.', 'Offer "Leave them in the dryer" next to the right answer and ask the question again in a new context.', 'Show crisp vegetables gone limp after a night in the dryer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
